   #[test]
   fn r5297000_an_immune_unit_s_own_evolve_text_after_the_state_check_evolved_it_is_no_spell_s() {
       use crate::rules::fixtures::evolution::{FULL, register_evolution_fixtures};

       // R4623000's board: p1's "Evolves when all your unit zones are full" Unit, Immune to Spells, one
       // zone short of full; a Spell's summon fills the row and the settled state check evolves it.
       let mut state = playing("r5297000");
       register_evolution_fixtures();
       let id = put(&mut state, FULL, slot(P1, Row::Units, 1), json!({})).id;
       find_instance_mut(&mut state, &id)
           .expect("the evolving Unit")
           .granted_keywords
           .push(Keyword::ImmuneToSpells);
       for lane in 2..UNIT_ZONES {
           put(&mut state, PLAIN, slot(P1, Row::Units, lane), json!({}));
       }
       let mut after = state.clone();
       let mut events = vec![marker(SPELL)];
       events.extend(settled(&mut after, effects::summon(json_as(json!({ "defId": PLAIN })))));
       let evolved = events
           .iter()
           .position(|event| matches!(event, GameEvent::Evolved { instance_id, .. } if *instance_id == id))
           .expect("the state check evolved it");
       // Its Evolve text runs with no marker of its own (C+ #49 Jay Fungus's "Evolve: Gain Poisonous",
       // fuzz seed 11717), so what it does to its own card follows the `evolved` in the Spell's run.
