           json_as(json!({ "type": "keywordGranted", "instanceId": id, "keyword": { "kind": "Poisonous" } }))
       };
       let mut own = events.clone();
       own.insert(evolved + 1, gain());
       assert_eq!(i21(&state, &own, &after), Vec::<String>::new());
       // Before its `evolved`, or after another run's marker, the same grant is the Spell's.
       let mut early = events.clone();
       early.insert(evolved, gain());
       only(&i21(&state, &early, &after), &id, &["I21", "keywordGranted", SPELL]);
       let mut marked = events.clone();
       marked.insert(evolved + 1, marker(SPELL));
       marked.insert(evolved + 2, gain());
       only(&i21(&state, &marked, &after), &id, &["I21", "keywordGranted", SPELL]);
   }
   ```

7. **Cards test.** In `crates/cards/tests/cross/invariants.rs`, insert this new module right before the doc comment `/// I2 and an animated card back in its backrow…` (after `mod i2_a_unit_gone_under_a_windfury_aura`):
   ```rust
   /// I2 and a Unit stolen later in the action that attacked twice inside it under its side's Windfury aura,
   /// which the state the action leaves no longer shows on the other side (R5297001: S+ #63 Overdrive Dome
   /// awake inside an autopilot turn, then M #39.5 Jade Beauty's Allure at the next turn's start; handicapped
   /// fuzz seed 15402).
   mod i2_r5297001_a_unit_stolen_later_under_a_windfury_aura {
       use super::*;

       const DOME: &str = "stinkyscapeplus-063";

       /// A Vanilla declares two attacks at p2's hero and is then stolen by p2, all inside one action, the Dome
       /// in p1's backrow when `dome`: the state the action leaves holds the Vanilla on p2's side, where p1's
       /// Dome gives it nothing (R4665002), entered on this turn by the steal.
       fn two_attacks_then_stolen(dome: bool) -> Vec<String> {
           let mut setup = json!({ "p2": { "field": [{ "def": VANILLA, "lane": 1 }] } });
           if dome {
               setup["p1"] = json!({ "backrow": [{ "def": DOME, "lane": 1 }] });
           }
           let mut g = scenario(setup);
           let unit = g.unit_at(PlayerId::P2, 1);
           let turn = g.state().turn;
           find_instance_mut(g.state_mut(), &unit.id)
               .expect("the stolen Vanilla")
               .summoned_turn = Some(turn);
           let mut monitor = create_invariant_monitor(g.state());
           let declared = || {
               event(json!({ "type": "attackDeclared", "attackerId": unit.id, "targetId": "hero-p2", "forced": false }))
           };
           let stolen = event(json!({
               "type": "controlChanged", "instanceId": unit.id, "controller": "p2", "row": "units", "lane": 1,
               "how": "steal",
           }));
           monitor.after(&[declared(), declared(), stolen], g.state())
       }

       #[test]
       fn r5297001_a_unit_stolen_later_that_attacked_twice_under_its_side_s_windfury_aura_is_one_windfury_turn() {
           assert_eq!(two_attacks_then_stolen(true), no_violations());
       }

       #[test]
       fn r5297001_a_unit_stolen_later_that_attacked_twice_with_no_windfury_aura_is_still_an_extra_attack() {
           let found = two_attacks_then_stolen(false);
           assert_eq!(found.len(), 1, "{found:?}");
           assert!(found[0].contains("I2 extra attack"), "{}", found[0]);
       }
   }
   ```

8. **`spec/rulings/R5297000.md`.**
   - Front matter:
     - `id: R5297000`
     - `title: "An immune Unit's own Evolve text after the state check evolved it is no Spell's, and I21 allows it (issue #5297)"`
     - `cards: "§4.5, §6.1, §6.2, R3536001, R4453000, R4623000; C+ #49 Jay Fungus, M #21 API Key Fishing (issue #5297)"`
     - `proven_in: [crates/engine/tests/rules/invariants.rs]`, written as a YAML list like the other notes.
   - Body, one paragraph each:
     - **(a) What happened.** In super run 46136502155's `fuzz (3/4)`, plain seed 11717: p2's Jay Fungus, given Immune to Spells, met its "Evolves when" at p2's end of turn. Its own discount and API Key Fishing's end-of-turn add of a (0)-cost copy did that. The settled state check evolved it ([[R3536001]]), an `evolved` [[R4623000]] allows. The queued Evolve text then ran with no marker (`hook_marks::hook_kind_of` names no `evolve`), so its `keywordGranted` fell in API Key Fishing's run, a Spell's, and I21 named the Spell. [[R4623000]] took the Evolve text to run under the card's own marker; it has none.
     - **(b) "This is the card's own text."** [[§6.2]]'s Evolve text belongs to the card that evolves; [[§6.1]] keeps only a Spell's effects off it ([[R4453000]]).
     - **(c) "What I21 allows."** An event naming the Unit after its own `evolved` in the same run (no marker, trap, turn edge, AI turn or play between), while its "Evolves when" holds after the step as [[R4623000]] reads it. The same event before its `evolved`, or after another run's marker, is still judged. A Spell's own later change to a Unit its `evolve` verb evolved, whose condition then holds, passes too: the gap [[R4623000]] already accepts.
     - **(d)** "Hearthstone semantics: a minion's own triggered text is the minion's, whatever spell set the board that triggered it."
     - **(e) Rejected, two alternatives.** First, a new `HookKind` marker for the Evolve text: it changes the wire, its generated types and the client's animation anchors for a presentation-only marker, and [[R4623000]] rejected one for these evolutions. Second, reading every event after a standing `evolved` as the evolving card's until the next marker: that would let a Spell's reach of another immune Unit through.

9. **`spec/rulings/R5297001.md`.**
   - Front matter:
     - `id: R5297001`
     - `title: "A Unit stolen later in the action that attacked twice under its side's Windfury aura is read as one gone, and I2 allows it (issue #5297)"`
     - `cards: "§4.1, §6.1, R12, R636, R963, R1844000, R3556008, R4665002; S+ #63 Overdrive Dome, M #39.5 Jade Beauty, S #47 Circadian Fullcycler (issue #5297)"`
     - `proven_in: [crates/cards/tests/cross/invariants.rs]`
   - Body, one paragraph each:
     - **(a) What happened.** In the same run's `fuzz (4/4)`, handicapped seed 15402: p1's end of turn ran p2's whole turn in one action under S #47's autopilot ([[R1844000]]). At its start p2's Overdrive Dome woke and gave p2's Units Windfury ([[R3556008]]). A Drone Corvette attacked twice, as [[R636]] lets it. At p1's next turn start, in the same action, Jade Beauty's Allure stole it ([[R963]], [[R12]]). On p1's side the Dome, which reaches its controller's Units alone ([[R4665002]]), gives it nothing. I2 reads Windfury as the step before left it (the Dome was Dormant then) or as the action leaves it, so it named the second attack.
     - **(b) "What I2 allows."** I2 already reads a Unit gone by the action's end as one that may have attacked under an aura that woke inside it (`aura_gives_windfury`; fuzz seeds 1596 and 2217). A Unit with a `controlChanged` later in the action is read the same way: the state the action leaves shows it on the other side, which says nothing of the side it attacked from. With no Windfury aura on the board after the step, its second attack is still an extra one.
     - **(c) Rejected.** Reading the stolen Unit as standing on the side it attacked from: the steal's event names only its new side, and a Unit that changes sides twice in one action would need each.

