   /// I2 and a Unit stolen later in the action that attacked twice inside it under its side's Windfury aura,
   /// which the state the action leaves no longer shows on the other side (R5297001: S+ #63 Overdrive Dome
   /// awake inside an autopilot turn, then M #39.5 Jade Beauty's Allure at the next turn's start; handicapped
   /// fuzz seed 15402).
   mod i2_r5297001_a_unit_stolen_later_under_a_windfury_aura {
       use super::*;

       const DOME: &str = "stinkyscapeplus-063";

       /// A Vanilla declares two attacks at p2's hero and is then stolen by p2, all inside one action, the Dome
       /// in p1's backrow when `dome`: the state the action leaves holds the Vanilla on p2's side, where p1's
       /// Dome gives it nothing (R4665002), entered on this turn by the steal.
       fn two_attacks_then_stolen(dome: bool) -> Vec<String> {
           let mut setup = json!({ "p2": { "field": [{ "def": VANILLA, "lane": 1 }] } });
           if dome {
               setup["p1"] = json!({ "backrow": [{ "def": DOME, "lane": 1 }] });
