               event(json!({ "type": "attackDeclared", "attackerId": unit.id, "targetId": "hero-p2", "forced": false }))
           };
           let stolen = event(json!({
               "type": "controlChanged", "instanceId": unit.id, "controller": "p2", "row": "units", "lane": 1,
               "how": "steal",
