   /// I21: whether `event` ends the run open before it, as the walk in `immune_reach_findings` reads it: a
   /// marker, a trap, a turn edge, the AI's turn, or a play's start or end.
   fn ends_a_run(event: &GameEvent) -> bool {
       matches!(
           event,
           GameEvent::HookResolving { .. }
               | GameEvent::TrapFired { .. }
               | GameEvent::TurnEnded { .. }
               | GameEvent::TurnStarted { .. }
               | GameEvent::AutopilotEngaged { .. }
               | GameEvent::CardPlayed { .. }
               | GameEvent::CardResolved { .. }
       )
   }

   /// I21, R5297000: whether `id`'s own `evolved` came in the run open now (`before`, the step's events ahead of
   /// the one judged, back to the last run's start). The settled state check queues a standing evolution's
   /// Evolve text behind it (`evolution::evolve_standing`), and that run marks nothing (`hook_marks::hook_kind_of`
   /// names no `evolve`), so what it does to its own card lands in whatever run was open: C+ #49 Jay Fungus's
   /// "Gain Poisonous" in M #21 API Key Fishing's end-of-turn run (fuzz seed 11717).
   fn evolved_in_the_run(before: &[GameEvent], id: &str) -> bool {
       before
           .iter()
           .rev()
           .take_while(|event| !ends_a_run(event))
           .any(|event| matches!(event, GameEvent::Evolved { instance_id, .. } if instance_id == id))
   }
   ```

